import{_ as i,o as t,c as a,j as e,a as n,a3 as o}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/unterricht-kataloge/kataloge-personengruppen-01.png",s="/bilder/unterricht-kataloge/kataloge-personengruppen-02.png",p="/bilder/unterricht-kataloge/kataloge-personengruppen.png",u="/bilder/unterricht-kataloge/kataloge-personengruppen-export.png",g="/bilder/unterricht-kataloge/kataloge-personengruppen-export-vorschau.png",S=JSON.parse('{"title":"Personengruppen und ihre Kontakte verwalten","description":"","frontmatter":{"title":"Personengruppen und ihre Kontakte verwalten","source_pageid":313,"source_revision":7022},"headers":[],"relativePath":"schild3/unterricht-kataloge/personengruppen-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/personengruppen-schulbezogene-kataloge.md"}'),h={name:"schild3/unterricht-kataloge/personengruppen-schulbezogene-kataloge.md"};function d(c,r,f,m,k,b){return t(),a("div",null,[...r[0]||(r[0]=[e("h1",{id:"personengruppen-und-ihre-kontakte-verwalten",tabindex:"-1"},[n("Personengruppen und ihre Kontakte verwalten "),e("a",{class:"header-anchor",href:"#personengruppen-und-ihre-kontakte-verwalten","aria-label":'Permalink to "Personengruppen und ihre Kontakte verwalten"'},"​")],-1),e("p",null,"Stellen Sie Gruppen aus Schülerinnen, Schülern, Lehrkräften, Erziehungsberechtigten und weiteren Kontakten zusammen. Die Anleitung beschreibt Zuordnung, Ausgabe und Export.",-1),e("p",null,[n("Über den Katalog "),e("strong",null,"Personengruppen"),n(" können Gruppen mit individuellem Namen definiert werden. In jeder Gruppe können beliebige Personen mit ihren Kontaktdaten aufgenommen werden. Es ist ebenso möglich, Schülerinnen, Schülern, Lehrkräften oder Erziehungsberechtigten einer solchen Personengruppe zuzuordnen. Sie haben so schnellen Zugriff auf Personen, deren Kontaktdaten für die Schule regelmäßig benötigt werden.")],-1),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("ul",null,[e("li",null,"Schulkonferenzmitglieder aus Erziehungsberechtigten, Schülerinnen, Schülern und Lehrkräften"),e("li",null,"Schulische Mitarbeiter bestehend aus Hausmeister und Sekretariat"),e("li",null,"Städtische Mitarbeiter aus dem Schulamt bestehend aus externen Personen.")])],-1),o('<h2 id="anlegen-oder-loschen-einer-personengruppe" tabindex="-1">Anlegen oder Löschen einer Personengruppe <a class="header-anchor" href="#anlegen-oder-loschen-einer-personengruppe" aria-label="Permalink to &quot;Anlegen oder Löschen einer Personengruppe&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/kataloge-personengruppen-01.png"><img src="'+l+'" alt="Übersicht über Kataloge ➜ Personengruppen." loading="lazy"></a></p><p><em>Übersicht über Kataloge ➜ Personengruppen.</em></p><p>Klicken Sie in der Navigationsleiste der Personengruppen auf die Schaltfläche <strong>Datensatz einfügen (+)</strong>. Vergeben Sie einen Gruppennamen für den neuen Datensatz.</p><p>Links neben jedem Gruppennamen finden Sie ein Aufklappsymbol (+), über das weitere Detailinformationen zur Personengruppe optional eingetragen werden können (<em>Zusatzinfo</em>, <em>Gruppenart</em>, <em>Sammel-E-Mail-Adresse</em>).</p><p>Sie können den Gruppennamen und die Detailinformationen zur Gruppe jederzeit abändern.</p><p>Klicken Sie in der Navigationsleiste der Personengruppen auf die Schaltfläche <strong>Datensatz löschen (-)</strong>, um eine Personengruppe zu löschen. Hierbei wird die Gruppendefinition gelöscht. Es werden ebenfalls alle manuell der Gruppe hinzugefügten Personen gelöscht, welche nicht der Gruppe der Schülerschaft, der Lehrkräfte oder der Erziehungsberechtigten angehören.</p><h2 id="hinzufugen-von-personen-zur-gruppe" tabindex="-1">Hinzufügen von Personen zur Gruppe <a class="header-anchor" href="#hinzufugen-von-personen-zur-gruppe" aria-label="Permalink to &quot;Hinzufügen von Personen zur Gruppe&quot;">​</a></h2><h3 id="schulerin-oder-schuler-hinzufugen" tabindex="-1">Schülerin oder Schüler hinzufügen <a class="header-anchor" href="#schulerin-oder-schuler-hinzufugen" aria-label="Permalink to &quot;Schülerin oder Schüler hinzufügen&quot;">​</a></h3><ol><li>Öffnen Sie <strong>Schüler</strong> und markieren Sie links in der Namensliste die gewünschten Personen.</li><li>Klicken Sie mit der rechten Maustaste auf einen markierten Namen.</li><li>Wählen Sie <strong>Markierte Datensätze zu allgemeiner Personengruppe hinzufügen</strong>.</li><li>Wählen Sie die Personengruppe und bestätigen Sie mit <strong>OK</strong>.</li></ol><h3 id="lehrkraft-hinzufugen" tabindex="-1">Lehrkraft hinzufügen <a class="header-anchor" href="#lehrkraft-hinzufugen" aria-label="Permalink to &quot;Lehrkraft hinzufügen&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/kataloge-personengruppen-02.png"><img src="'+s+'" alt="Hinzufügen einer Lehrkraft zu einer Personengruppe." loading="lazy"></a></p><p><em>Hinzufügen einer Lehrkraft zu einer Personengruppe.</em></p><ol><li>Öffnen Sie <strong>Lehrkräfte</strong> und wählen Sie die gewünschte Person.</li><li>Klicken Sie mit der rechten Maustaste auf ihren Namen.</li><li>Wählen Sie <strong>Zu allgemeiner Personengruppe hinzufügen</strong>.</li><li>Wählen Sie die Personengruppe und bestätigen Sie mit <strong>OK</strong>.</li></ol><p>Lehrkräfte werden einzeln einer Personengruppe hinzugefügt.</p><h3 id="erziehungsberechtigte-hinzufugen" tabindex="-1">Erziehungsberechtigte hinzufügen <a class="header-anchor" href="#erziehungsberechtigte-hinzufugen" aria-label="Permalink to &quot;Erziehungsberechtigte hinzufügen&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/kataloge-personengruppen.png"><img src="'+p+'" alt="Hinzufügen von Erziehungsberechtigten zu einer Personengruppe." loading="lazy"></a></p><p><em>Hinzufügen von Erziehungsberechtigten zu einer Personengruppe.</em></p><ol><li>Öffnen Sie <strong>Schüler → Erziehungsberechtigte/Telefonnummern</strong>.</li><li>Klicken Sie bei der gewünschten Person mit der rechten Maustaste in <strong>Anrede</strong>, <strong>Titel</strong>, <strong>Name</strong> oder <strong>Vorname</strong>.</li><li>Wählen Sie <strong>Zu allgemeiner Personengruppe hinzufügen</strong>.</li><li>Wählen Sie die Personengruppe und bestätigen Sie mit <strong>OK</strong>.</li></ol><p>Erziehungsberechtigte werden einzeln einer Personengruppe hinzugefügt.</p><h3 id="neue-personen-hinzufugen" tabindex="-1">Neue Personen hinzufügen <a class="header-anchor" href="#neue-personen-hinzufugen" aria-label="Permalink to &quot;Neue Personen hinzufügen&quot;">​</a></h3><ol><li>Öffnen Sie <strong>Kataloge → Personengruppen</strong>.</li><li>Wählen Sie unter <strong>Alle Gruppen</strong> die gewünschte Gruppe. Unter <strong>Mitglieder der Gruppe „Gruppenname“</strong> sehen Sie die bisherigen Mitglieder.</li><li>Klicken Sie in der Navigationsleiste dieser Mitgliederliste auf <strong>Datensatz einfügen (+)</strong>.</li><li>Füllen Sie <strong>Details zur Person</strong> aus.</li><li>Speichern Sie das neue Mitglied mit <strong>Datensatz übernehmen (✓)</strong>.</li></ol><h2 id="entfernen-von-personen-aus-einer-personengruppe" tabindex="-1">Entfernen von Personen aus einer Personengruppe <a class="header-anchor" href="#entfernen-von-personen-aus-einer-personengruppe" aria-label="Permalink to &quot;Entfernen von Personen aus einer Personengruppe&quot;">​</a></h2><p>Wechseln Sie auf den Reiter Kataloge ➜ <strong>Personengruppen</strong>. Markieren Sie im Bereich <strong>Mitglieder der Gruppe &quot;Gruppenname&quot;</strong> ein Mitglied. Klicken Sie in der Navigationsleiste der Mitglieder auf die Schaltfläche <strong>Datensatz löschen (-)</strong>.</p><h2 id="exportieren-von-personengruppen" tabindex="-1">Exportieren von Personengruppen <a class="header-anchor" href="#exportieren-von-personengruppen" aria-label="Permalink to &quot;Exportieren von Personengruppen&quot;">​</a></h2><h3 id="in-eine-excel-tabelle" tabindex="-1">In eine Excel-Tabelle <a class="header-anchor" href="#in-eine-excel-tabelle" aria-label="Permalink to &quot;In eine Excel-Tabelle&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/kataloge-personengruppen-export.png"><img src="'+u+'" alt="Excel-Export einer Personengruppe über die Rechte Maustaste." loading="lazy"></a></p><p><em>Excel-Export einer Personengruppe über die Rechte Maustaste.</em></p><p>Wechseln Sie auf den Reiter Kataloge ➜ <strong>Personengruppen</strong>.</p><p>Klicken Sie im Bereich <strong>Mitglieder der Gruppe &quot;Gruppenname&quot;</strong> mit der <code>rechten Maustaste</code> auf ein Gruppenmitglied.</p><p>Wählen Sie im Kontextmenü den <strong>Excel-Export</strong>. Es öffnet sich ein Fenster, welches eine Voransicht der Excel-Tabelle anzeigt.</p><p><a href="/bilder/unterricht-kataloge/kataloge-personengruppen-export-vorschau.png"><img src="'+g+'" alt="Speichern Sie Ihre Personengruppe." loading="lazy"></a></p><p><em>Speichern Sie Ihre Personengruppe.</em></p><p>Über die Schaltfläche <strong>Speichern</strong> können sie die Gruppe exportieren.</p><h3 id="in-eine-schnittstellen-dat-datei" tabindex="-1">In eine Schnittstellen-DAT-Datei <a class="header-anchor" href="#in-eine-schnittstellen-dat-datei" aria-label="Permalink to &quot;In eine Schnittstellen-DAT-Datei&quot;">​</a></h3><p>Wechseln Sie auf den Reiter <strong>Verwaltung ➜ Export ➜ Schnittstelle SchILD-NRW</strong>. Sie finden dort die Option <strong>Personengruppen</strong> als eine der Schnittstellendateien als DAT-Datei zu exportieren. Beim Export werden eine <em>Personengruppen.dat</em> und eine Datei <em>Personengruppen_Personen.dat</em> gespeichert.</p><h2 id="personengruppen-drucken" tabindex="-1">Personengruppen drucken <a class="header-anchor" href="#personengruppen-drucken" aria-label="Permalink to &quot;Personengruppen drucken&quot;">​</a></h2><p>Verwenden Sie in Reports, in denen Personengruppen und die zugehörigen Personen aufgelistet werden sollen, die <em>Hauptdatenquelle</em> <strong>Personengruppen</strong> und die Unterdatenquelle <strong>Personengruppen_Personen</strong>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Personengruppen_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7022.</p>',40)])])}const P=i(h,[["render",d]]);export{S as __pageData,P as default};
